import{_ as t,o as n,c as s,a6 as a}from"./chunks/framework.CCKCzdWs.js";const r="/screenshots/credentials-per-user.png",g=JSON.parse('{"title":"Per-user credentials","description":"Run a CI action on Jenkins, GitLab or Bitbucket in the name of whoever starts it from Piwi, with their own token and rights, through one credential an administrator sets up once.","frontmatter":{"title":"Per-user credentials","description":"Run a CI action on Jenkins, GitLab or Bitbucket in the name of whoever starts it from Piwi, with their own token and rights, through one credential an administrator sets up once.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/per-user-credentials.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/per-user-credentials.html"}],["meta",{"property":"og:title","content":"Per-user credentials | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Run a CI action on Jenkins, GitLab or Bitbucket in the name of whoever starts it from Piwi, with their own token and rights, through one credential an administrator sets up once."}]]},"headers":[],"relativePath":"operate/per-user-credentials.md","filePath":"operate/per-user-credentials.md","lastUpdated":1795800974000}'),o={name:"operate/per-user-credentials.md"};function i(h,e,d,c,l,u){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="per-user-credentials" tabindex="-1">Per-user credentials <a class="header-anchor" href="#per-user-credentials" aria-label="Permalink to &quot;Per-user credentials&quot;">​</a></h1><p>A per-user credential runs a CI action in the name of whoever starts it. A shared <a href="./credentials.html">credential</a> sends one secret, so Jenkins shows its account (a <code>piwi-bot</code>) as the user who started every build and applies that account&#39;s rights. A per-user credential holds no user and no secret: an administrator sets it up once, each person gives their own Jenkins user name and API token for it, and a build started from Piwi shows &quot;Started by user alice&quot; and runs with Alice&#39;s rights.</p><figure><img src="'+r+'" alt="A per-user Jenkins credential&#39;s panel: it acts as whoever starts an action, each person&#39;s own token, the three people who gave theirs with their Jenkins account and its state, one refused by Jenkins, and its log with Quinn&#39;s dispatch and Jordan&#39;s, which Jenkins refused"><figcaption>A per-user credential&#39;s panel: who gave their token, as which Jenkins account, and its log.</figcaption></figure><h2 id="set-one-up" tabindex="-1">Set one up <a class="header-anchor" href="#set-one-up" aria-label="Permalink to &quot;Set one up&quot;">​</a></h2><p>In <strong>Settings → Credentials</strong>, <strong>New credential</strong>, service <strong>CI server</strong>, then <strong>Who it acts as</strong> → <strong>Per user</strong>. Only an administrator (the <code>credentials:manage</code> permission) creates or changes one, and creates it only while sign-in is on: it collects other people&#39;s tokens, so its destination is one an administrator chose. The destination is https, or a host <code>PIWI_CI_SERVER_HOSTS</code> lists, since a token is never sent in the clear. Its fields are a shared credential&#39;s without the user and the secret, plus an optional link to the page where a person creates their token (Jenkins: their user&#39;s <strong>Security</strong> page).</p><p>A Project admin then picks it in a CI server action&#39;s <strong>Credential</strong>, as any credential shared with the project. It never goes with a Custom request. To bound what a token can build, give the credential a folder as its destination (<code>https://jenkins.example.com/job/qa/</code>): an action outside it is refused.</p><h2 id="give-your-token" tabindex="-1">Give your token <a class="header-anchor" href="#give-your-token" aria-label="Permalink to &quot;Give your token&quot;">​</a></h2><p>Each person gives their token once, under <strong>Account → Credentials</strong>, or in the run dialog the first time they start an action on it. The form says where the token goes and who set the credential up. Piwi tests the token before saving it, by reading Jenkins&#39; <code>whoAmI</code> at the root of the destination, and keeps the account Jenkins names.</p><ul><li><strong>An API token only</strong>: 32 or 34 hexadecimal characters, as Jenkins makes them. An account password, which Jenkins also takes, is refused and never stored.</li><li><strong>One account per person</strong>: a token for a Jenkins account another person already gave is refused, so a shared service account cannot be saved as someone&#39;s own.</li><li><strong>10 tests per person and credential in 10 minutes</strong>, and a failed test says only that Jenkins refused the token, did not recognize it as a signed-in user, could not be reached, or is on a private address <code>PIWI_CI_SERVER_HOSTS</code> does not list, never Jenkins&#39; own answer.</li></ul><p><strong>Test</strong> sends the saved token again; <strong>Remove</strong> takes it out of Piwi. A removed token stays valid on Jenkins: revoke it there too.</p><h2 id="gitlab-and-bitbucket" tabindex="-1">GitLab and Bitbucket <a class="header-anchor" href="#gitlab-and-bitbucket" aria-label="Permalink to &quot;GitLab and Bitbucket&quot;">​</a></h2><p>A per-user <strong>Source control</strong> credential runs a GitLab pipeline or a Bitbucket custom pipeline in the name of whoever starts it. Each person authorizes it once at the host, in a popup, instead of typing a token: the host shows the pipeline as theirs, and its rights apply. A GitHub destination cannot be per user: the form offers it for GitLab and Bitbucket only.</p><ul><li><strong>Set it up</strong>: register an OAuth application, on GitLab (scope <code>api</code>, on gitlab.com or a host <code>PIWI_SCM_GITLAB_HOSTS</code> lists) or on Bitbucket (an OAuth consumer with the Account read, Repositories read and Pipelines write permissions), with the callback URL the credential form shows. Then create the credential with service <strong>Source control</strong>, the host&#39;s API as destination, <strong>Per user</strong>, and the application&#39;s client id and secret. The secret is sealed with the host&#39;s token endpoint and sent only to its OAuth endpoints (token and revocation).</li><li><strong>Authorize</strong>: <strong>Authorize with GitLab</strong> (or Bitbucket) under <strong>Account → Credentials</strong>, or in the run dialog. The authorization is bound to you and the credential, used once, and expires after 10 minutes; Piwi then reads the account the token belongs to and keeps it.</li><li><strong>Refresh and revocation</strong>: an access token is refreshed when it is used within 5 minutes of its expiry, and marked refused when the host refuses the refresh. <strong>Remove</strong>, an administrator&#39;s removal and the deletion of an account revoke a GitLab token at GitLab; Bitbucket offers no revocation, so revoke it in Bitbucket&#39;s settings.</li></ul><p>A per-user source control credential serves CI actions only, never a project&#39;s or the instance&#39;s source control.</p><h2 id="what-runs-in-your-name" tabindex="-1">What runs in your name <a class="header-anchor" href="#what-runs-in-your-name" aria-label="Permalink to &quot;What runs in your name&quot;">​</a></h2><ul><li><strong>Only from a signed-in page.</strong> An API key, an MCP agent included, never starts an action in someone&#39;s name: the request is refused before anything is sent.</li><li><strong>Only your own token.</strong> A person without one is asked for it before the dispatch is sent or stored; a token is never sent for anyone else.</li><li><strong>Only the action you saw.</strong> The run dialog shows the job, the fixed inputs and your Jenkins account, and a dispatch refuses an action changed since the dialog showed it.</li><li><strong>A token Jenkins refuses</strong> (401) is marked refused and no longer sent, until you give it again or a test passes.</li></ul><p>The action editor&#39;s credential picker says which credential runs in the starter&#39;s name; its <strong>Check</strong> and job listings read with the editor&#39;s own token.</p><h2 id="what-an-administrator-sees" tabindex="-1">What an administrator sees <a class="header-anchor" href="#what-an-administrator-sees" aria-label="Permalink to &quot;What an administrator sees&quot;">​</a></h2><p>The credential&#39;s panel lists who gave a token, with their Jenkins account, its state and its last use, never the token, and removes one or all. <strong>Disable</strong> stops every token at once. A new destination removes every token, each sealed with the one it leaves. The log names each use&#39;s person, and their Jenkins account for a use of their saved token, and counts each person&#39;s reads in rows of their own.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./credentials.html">Credentials</a>: the fields, the checks and the log every credential shares</li><li><a href="/features/ci-actions.html">CI actions</a>: the CI server action that names the credential</li><li><a href="/features/ci-rerun.html">CI re-run</a>: the run dialog that asks for your token</li><li><a href="./project-access.html">Access, roles and groups</a>: who holds <code>credentials:manage</code></li></ul>',21)])])}const k=t(o,[["render",i]]);export{g as __pageData,k as default};
